// mixes live records with already-completed ones awaiting materialization.
func (s *State) LiveTaskRecords() []TaskRecord {
	var live []TaskRecord
	for _, r := range s.TaskRecords {
		if r.CompletedAt.IsZero() {
			live = append(live, r)
		}
	}
	return live
}

